changeSet.sql:
insert into permission (name) values ('REGISTER_LMS');

insert into role_permission (role_id, permission_id)
select r.id, p.id
from role r
join permission p on p.name = 'REGISTER_LMS'
where r.name = 'ADMIN';

rollback.sql:
delete rp from role_permission rp
join permission p on p.id = rp.permission_id
where p.name = 'REGISTER_LMS';

delete from permission where name = 'REGISTER_LMS';
